@Override
  public float modifyDamageTaken(IToolStackView tool, ModifierEntry modifier, EquipmentContext context, EquipmentSlot slotType, DamageSource source, float amount, boolean isDirectDamage) {
    if (!source.is(DamageTypeTags.BYPASSES_INVULNERABILITY)) {
      int level = SlotInChargeModule.getLevel(context.getTinkerData(), SLOT_KEY, slotType);
      if (level > 0) {
        // step 1: reduce damage based on the current effect level
        MobEffect effect = TinkerModifiers.momentumEffect.get(ToolType.ARMOR);
        LivingEntity entity = context.getEntity();
        amount -= TinkerEffect.getLevel(entity, effect);

        // step 2: apply momentum based on damage taken
        int reduction = (int)(percent.compute(level) * amount);
        if (reduction > 0) {
          entity.addEffect(new MobEffectInstance(effect, duration.compute(level), reduction - 1, false, false, true));
        }
      }
    }
    return amount;
  }

@Override
  public void addModules(Builder builder) {
    builder.addModule(new SlotInChargeModule(SLOT_KEY));
  }

public static int getLevel(LivingEntity entity, MobEffect effect) {
    return getAmplifier(entity, effect) + 1;
  }

public static int getAmplifier(LivingEntity entity, MobEffect effect) {
    MobEffectInstance instance = entity.getEffect(effect);
    if (instance != null) {
      return instance.getAmplifier();
    }
    return -1;
  }

private boolean toolValid(IToolStackView tool, EquipmentSlot slot, EquipmentChangeContext context) {
    return !tool.isBroken() && !context.getEntity().level().isClientSide && ArmorLevelModule.validSlot(tool, slot, heldTag);
  }

@Override
  public void onEquip(IToolStackView tool, ModifierEntry modifier, EquipmentChangeContext context) {
    EquipmentSlot slot = context.getChangedSlot();
    if (toolValid(tool, slot, context)) {
      context.getTinkerData().ifPresent(data -> data.computeIfAbsent(key, CONSTRUCTOR).addSlot(slot, modifier.getLevel()));
    }
  }

@Override
  public void onUnequip(IToolStackView tool, ModifierEntry modifier, EquipmentChangeContext context) {
    // remove slot in charge if that is us
    EquipmentSlot slot = context.getChangedSlot();
    if (toolValid(tool, slot, context)) {
      context.getTinkerData().ifPresent(data -> {
        SlotInCharge slotInCharge = data.get(key);
        if (slotInCharge != null) {
          slotInCharge.removeSlot(slot);
        }
      });
    }
  }

private void addSlot(EquipmentSlot slotType, int level) {
      int index = slotType.getFilterFlag();
      totalLevel += level - levels[index];
      levels[index] = level;
      // prefer armor in charge as hand only runs when blocking, prefer mainhand over offhand
      if (inCharge == null || (inCharge.getType() == Type.HAND && slotType != EquipmentSlot.OFFHAND)) {
        inCharge = slotType;
      }
    }

private void removeSlot(EquipmentSlot slotType) {
      int index = slotType.getFilterFlag();
      totalLevel -= levels[index];
      levels[index] = 0;
      // prioritize armor slots
      for (EquipmentSlot armorSlot : ModifiableArmorMaterial.ARMOR_SLOTS) {
        if (levels[armorSlot.getFilterFlag()] > 0) {
          inCharge = armorSlot;
          return;
        }
      }
      // if none, find a hand slot
      for (EquipmentSlot hand : InteractionHandler.HAND_SLOTS) {
        if (levels[hand.getFilterFlag()] > 0) {
          inCharge = hand;
          return;
        }
      }
      inCharge = null;
    }

public static int getLevel(LazyOptional<TinkerDataCapability.Holder> capability, TinkerDataKey<SlotInCharge> key, EquipmentSlot slot) {
    TinkerDataCapability.Holder data = LogicHelper.orElseNull(capability);
    if (data != null) {
      SlotInCharge inCharge = data.get(key);
      return inCharge != null && inCharge.inCharge == slot ? inCharge.totalLevel : 0;
    }
    return 0;
  }

public static boolean validSlot(IToolStackView tool, EquipmentSlot slot, @Nullable TagKey<Item> heldTag) {
    return slot.isArmor() || heldTag != null && tool.hasTag(heldTag);
  }

private static void onEquipmentChange(LivingEquipmentChangeEvent event) {
    runModifierHooks(event.getEntity(), event.getSlot(), event.getFrom(), event.getTo());
  }

private static void runModifierHooks(LivingEntity entity, EquipmentSlot changedSlot, ItemStack original, ItemStack replacement) {
    EquipmentChangeContext context = new EquipmentChangeContext(entity, changedSlot, original, replacement);

    // first, fire event to notify an item was removed
    IToolStackView tool = context.getOriginalTool();
    if (tool != null && ModifierUtil.validArmorSlot(tool, changedSlot)) {
      for (ModifierEntry entry : tool.getModifierList()) {
        entry.getHook(ModifierHooks.EQUIPMENT_CHANGE).onUnequip(tool, entry, context);
      }
    }

    // next, fire event to notify an item was added
    tool = context.getReplacementTool();
    if (tool != null && ModifierUtil.validArmorSlot(tool, changedSlot)) {
      for (ModifierEntry entry : tool.getModifierList()) {
        entry.getHook(ModifierHooks.EQUIPMENT_CHANGE).onEquip(tool, entry, context);
      }
    }

    // finally, fire events on all other slots to say something changed
    for (EquipmentSlot otherSlot : EquipmentSlot.values()) {
      if (otherSlot != changedSlot) {
        tool = context.getValidTool(otherSlot);
        if (tool != null) {
          for (ModifierEntry entry : tool.getModifierList()) {
            entry.getHook(ModifierHooks.EQUIPMENT_CHANGE).onEquipmentChange(tool, entry, context, otherSlot);
          }
        }
      }
    }
    // fire event for modifiers that want to watch equipment when not equipped
    MinecraftForge.EVENT_BUS.post(new ToolEquipmentChangeEvent(context));
  }

